    }
}

# Categorize files based on current directory
categories = defaultdict(list)
for f in all_files:
    parts = f.split(os.sep)
    dir_name = parts[0].lower() if parts else ''

    # Simple categorization based on directory name
    if 'vae' in dir_name:
