    elif 'text_encoder' in dir_name or 'clip' in dir_name or 'umt5' in dir_name or 'qwen' in dir_name or 'gemma' in dir_name or 'mistral' in dir_name:
        categories['text_encoders'].append(f)
    elif 'clip_vision' in dir_name:
        categories['clip_vision'].append(f)
    elif 'embedding' in dir_name:
        categories['embeddings'].append(f)
    elif 'controlnet' in dir_name:
        categories['controlnet'].append(f)
    elif 'style' in dir_name:
        categories['style_models'].append(f)
    elif 'diffusers' in dir_name:
        categories['diffusers'].append(f)
    elif 'diffusion' in dir_name:
        categories['diffusion_models'].append(f)
    else:
        categories['other'].append(f)

# Show categorization results
